"""Completa Kidō cujo texto ou ficha técnica ficou vazio, cortado ou embaralhado na conversão do PDF.
Parte vem do próprio livro (tabelas embaralhadas, reconstruídas); o restante é proposta de redação para o autor revisar."""
import json, pathlib
raiz = pathlib.Path(__file__).resolve().parent.parent
caminho = raiz / "src/regras/kidos.json"
k = json.loads(caminho.read_text(encoding="utf-8"))
por = {(x["tipo"], x["n"]): x for x in k}

def M(req, alc, vel, custo):
    return f"Requisito: {req} · Alcance: {alc} · Velocidade: {vel} · Custo: {custo} PR"

