for (t, n), (texto, meta) in P.items():
    x = por[(t, n)]
    if texto: x["texto"] = texto
    if meta: x["meta"] = meta

def anexar(t, n, fim=None, antes=None, substituir=None):
    x = por[(t, n)]
    if substituir:
        a, b = substituir
        assert a in x["texto"], (t, n)
        x["texto"] = x["texto"].replace(a, b)
    if fim:
        x["texto"] = x["texto"].rstrip(" …") + fim

